  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Approves a pending IPO application on behalf of the bank. The operation is only allowed when the application is currently in the PENDING state and the related customer is still eligible to apply for IPO. On a successful approval, two information emails are dispatched: one to the customer and one to the related company. The application status is then updated to APPROVAL.
   * Algorithm:
   *   1. If this.status != PENDING, return false.
   *   2. If this.customer.isEligibleForIPO() == false, return false.
   *   3. Create an Email for the customer and an Email for the company using Email.createEmailContent.
   *   4. Add the two created emails to this.emails.
   *   5. Set this.status = APPROVAL.
   *   6. Return true.
   * Related Features: amountOfMoney, share, status, allowance, company, customer, emails
   * Related Classes: Customer, Company, Email, ApplicationStatus
   * Input: None (operates on the receiver Application instance).
   * Output: boolean - true when the application is successfully approved; false when the application is not in PENDING state or the customer is no longer eligible.
   * Pre-condition: The Application must exist, its status must be PENDING, and the related Customer must be eligible to apply for IPO (Customer.isEligibleForIPO() == true).
   * Post-condition: On success, the Application's status is updated to APPROVAL and two Email instances (one addressed to the customer, one to the company) are added to the emails list. On failure, no state change occurs.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    if (getStatus() != ApplicationStatus.PENDING)
    {
      return false;
    }
    if (!getCustomer().isEligibleForIPO())
    {
      return false;
    }

    Email emailHelper = IpoFactory.eINSTANCE.createEmail();
    String content = emailHelper.createEmailContent(getCompany(), getShare(), getCustomer(), getAmountOfMoney());

    Email customerEmail = IpoFactory.eINSTANCE.createEmail();
    customerEmail.setReceiver(getCustomer().getEmail());
    customerEmail.setContent(content);

    Email companyEmail = IpoFactory.eINSTANCE.createEmail();
    companyEmail.setReceiver(getCompany().getEmail());
    companyEmail.setContent(content);

    getEmails().add(customerEmail);
    getEmails().add(companyEmail);

    setStatus(ApplicationStatus.APPROVAL);
    return true;
  }

